ValidationRule.errorConditionFormula:
AND($Setup.EnableValidationRule__c.VR_extend_update_privilege_to_superusers__c=False, $RecordType.DeveloperName = "Freight", NOT (ISNEW()) , NOT( CONTAINS($User.Profile_Name__c, "Administrator")), OR(AND(ISPICKVAL(PRIORVALUE( StageName) , "Closed - Accepted"),OR(ISPICKVAL(StageName, 'Identify'),ISPICKVAL(StageName, 'Qualify'),ISPICKVAL(StageName, 'Propose & Negotiate'))), AND(ISPICKVAL(PRIORVALUE( StageName) , "Closed - Not Accepted"),OR(ISPICKVAL(StageName, 'Closed - Accepted'),ISPICKVAL(StageName, 'Identify'),ISPICKVAL(StageName, 'Qualify'),ISPICKVAL(StageName, 'Propose & Negotiate')))),
ISCHANGED( StageName )
)
